mapper.select:
SELECT c.*, (SELECT COUNT(*) FROM category child WHERE child.parent_id = c.category_id) > 0 AS hasChildren FROM category c WHERE 1=1
AND (c.category_name LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.category_id ASC LIMIT #{limit} OFFSET #{offset}
